  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Bahasa Vietnam Terdengar Asing dan Sulit$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak orang ingin menyapa teman atau rekan dari Vietnam, tetapi bingung karena bahasa Vietnam memakai enam nada dan tulisan latin beraksen yang asing di mata. Tanpa panduan, orang cenderung menghindari bicara sama sekali atau mengucapkan kata dengan nada salah sehingga maknanya berubah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Sekilas tentang Tiếng Việt$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bahasa Vietnam (Tiếng Việt) adalah bahasa resmi Vietnam yang dipakai sekitar 85 juta orang. Ia ditulis dengan huruf latin plus tanda diakritik (misalnya ơ, ư, đ), dan memiliki enam nada yang mengubah arti kata. Kabar baiknya: tata bahasanya sederhana — kata kerja tidak berubah bentuk menurut waktu, dan struktur kalimat mirip bahasa Indonesia (subjek-predikat-objek).$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$txt$Catatan kecil atau ponsel untuk mencatat kosakata$txt$, $txt$Aplikasi kamus Vietnam-Indonesia/Inggris untuk cek nada$txt$, $txt$Rekaman audio penutur asli (bisa dari video atau kamus daring)$txt$, $txt$Waktu 20 menit latihan setiap hari$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah-langkah: Sapaan dan Frasa Kunci$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Sapa dengan "Xin chào" (dibaca sin cao) untuk halo, lalu tambahkan nama: "Xin chào, tôi là Ade" (halo, saya Ade).$txt$, $txt$Tanyakan kabar dengan "Bạn khỏe không?" (apa kabar?). Jawab "Tôi khỏe, cảm ơn" (saya baik, terima kasih).$txt$, $txt$Ucapkan terima kasih dengan "Cảm ơn" dan permisi dengan "Xin lỗi" — dua kata yang paling sering dipakai.$txt$, $txt$Perkenalkan asal: "Tôi đến từ Indonesia" (saya dari Indonesia).$txt$, $txt$Pelajari angka 1-5: một, hai, ba, bốn, năm — berguna untuk harga dan nomor.$txt$, $txt$Latih nada: dengarkan rekaman dan tirukan naik-turun suaranya; rekam suaramu lalu bandingkan.$txt$, $txt$Buat dialog mini 4 kalimat (sapa-tanya kabar-perkenalan-terima kasih) dan hafalkan.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Hal yang Perlu Diperhatikan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Nada yang salah bisa mengubah arti kata, misalnya "ma" bisa berarti hantu, ibu, kuda, atau nasi tergantung nadanya. Jangan khawatir berbuat salah — penutur asli biasanya tetap memahami dari konteks dan menghargai usaha. Hindari mengandalkan transliterasi latin tanpa tanda nada karena sering menyesatkan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Uji dirimu: sapa seorang teman dalam bahasa Vietnam dan sampaikan perkenalan 3 kalimat tanpa melihat catatan. Jika lancar, lanjutkan dengan topik makanan ("Tôi thích phở" — saya suka phở) dan arah ("Ở đâu?" — di mana?). Konsistensi latihan harian lebih penting daripada menghafal banyak kata sekaligus.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Batuk Kering Tak Berdahak yang Mengganggu$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Batuk kering adalah batuk tanpa dahak yang terasa gatal di tenggorokan dan sering kambuh di malam hari. Ia mengganggu tidur, pekerjaan, dan percakapan. Penyebabnya beragam: sisa flu, alergi, iritasi debu atau asap, udara kering, hingga naiknya asam lambung ke tenggorokan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Mengapa Tenggorokan Jadi Gatal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Batuk adalah refleks tubuh untuk membersihkan saluran napas dari iritan. Pada batuk kering, reseptor di tenggorokan menjadi sensitif sehingga sedikit rangsangan saja memicu batuk berulang. Lingkaran ini memperparah: batuk mengiritasi tenggorokan, tenggorokan yang teriritasi memicu batuk lagi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Persiapan: Yang Perlu Disiapkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$txt$Air putih hangat yang cukup$txt$, $txt$Madu murni (untuk usia di atas 1 tahun)$txt$, $txt$Pelembap udara (humidifier) bila ada$txt$, $txt$Masker saat berada di tempat berdebu$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Perawatan Mandiri$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Minum air hangat sedikit-sedikit sepanjang hari agar tenggorokan tetap lembap.$txt$, $txt$Konsumsi satu sendok madu sebelum tidur untuk melapisi tenggorokan — jangan berikan madu pada bayi di bawah 1 tahun.$txt$, $txt$Berkumurlah dengan air garam hangat 2-3 kali sehari untuk mengurangi gatal.$txt$, $txt$Hindari pemicu: asap rokok, debu, parfum menyengat, dan minuman sangat dingin.$txt$, $txt$Tidurkan kepala sedikit lebih tinggi agar lendir tidak menumpuk di tenggorokan.$txt$, $txt$Jaga kelembapan ruangan; udara AC yang kering memperparah batuk.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Kapan Harus ke Dokter$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Segera konsultasikan ke dokter bila batuk berlangsung lebih dari 3 minggu, disertai sesak napas atau bunyi mengi, batuk berdarah, demam tinggi yang tidak turun, nyeri dada, atau penurunan berat badan tanpa sebab. Artikel ini bersifat informasi umum dan bukan pengganti nasihat medis profesional.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pencegahan Jangka Panjang$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Kurangi paparan pemicu dengan rajin membersihkan debu, memakai masker di jalan berdebu, berhenti merokok, dan mengelola alergi atau asam lambung bila itu pemicunya. Bila batuk kering selalu kambuh di musim tertentu, catat polanya untuk dibahas dengan dokter.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa yang Membuat Sebuah Danau Sangat Dalam$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Kedalaman danau biasanya terbentuk oleh tiga proses: patahan tektonik yang membelah kerak bumi, gletser yang mengeruk lembah, atau kawah vulkanik yang terisi air. Danau tektonik cenderung paling dalam karena retakannya bisa menembus jauh ke bawah permukaan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Danau Baikal: Sang Juara Kedalaman$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Danau Baikal di Siberia, Rusia, adalah danau terdalam di dunia dengan kedalaman maksimum sekitar 1.642 meter — cukup untuk menenggelamkan Menara Eiffel lebih dari lima kali lipat. Baikal juga danau air tawar tertua (sekitar 25 juta tahun) dan menyimpan sekitar seperlima cadangan air tawar permukaan dunia. Ia terbentuk di zona retakan aktif, sehingga dasarnya masih terus melebar beberapa milimeter per tahun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Pesaing Berikutnya: Tanganyika dan Laut Kaspia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Danau Tanganyika di Afrika Timur menempati posisi kedua dengan kedalaman sekitar 1.470 meter, sekaligus danau air tawar terpanjang di dunia. Laut Kaspia — yang secara teknis danau terbesar di dunia — mencapai kedalaman sekitar 1.025 meter di cekungan selatannya. Keduanya juga terbentuk oleh aktivitas tektonik.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Danau Dalam Lain yang Unik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Danau Vostok di Antartika terkubur di bawah hampir 4 kilometer es dan menyimpan air yang terisolasi jutaan tahun — laboratorium alami bagi ilmuwan. Danau Crater di Amerika Serikat terbentuk di kaldera gunung berapi dan terkenal dengan airnya yang sangat jernih. Danau Toba di Sumatra, danau vulkanik terbesar di dunia, memiliki kedalaman sekitar 500 meter.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Mengapa Danau Dalam Penting bagi Ilmu Pengetahuan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Lapisan sedimen di dasar danau dalam merekam sejarah iklim bumi hingga jutaan tahun ke belakang, seperti arsip raksasa. Ekosistemnya yang terisolasi juga melahirkan spesies endemik: Baikal saja menjadi rumah bagi sekitar 1.700 spesies tumbuhan dan hewan yang tidak ditemukan di tempat lain, termasuk anjing laut air tawar Baikal.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Machine Learning$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Machine learning (pembelajaran mesin) adalah cabang kecerdasan buatan (AI) yang memungkinkan komputer belajar pola dari data tanpa diprogram secara eksplisit untuk setiap aturan. Alih-alih menulis "jika ini maka itu" untuk semua kasus, kita memberi mesin banyak contoh, dan ia menyimpulkan polanya sendiri.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Tiga Cara Utama Mesin Belajar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pertama, pembelajaran terawasi (supervised learning): mesin belajar dari contoh yang sudah berlabel, seperti ribuan foto kucing yang ditandai "kucing", hingga ia bisa mengenali kucing baru. Kedua, pembelajaran tak terawasi (unsupervised learning): mesin mencari pola sendiri dalam data tanpa label, misalnya mengelompokkan pelanggan berdasarkan kebiasaan belanja. Ketiga, pembelajaran penguatan (reinforcement learning): mesin belajar lewat coba-coba dan hadiah, seperti AI yang belajar bermain catur dengan memainkan jutaan partai melawan dirinya sendiri.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Machine Learning di Sekitar Kita$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Teknologi ini sudah dipakai setiap hari: rekomendasi film dan musik, filter spam email, pengenalan wajah untuk membuka ponsel, terjemahan bahasa otomatis, asisten suara, hingga deteksi penipuan di transaksi bank. Model bahasa besar yang bisa diajak bercakap-cakap juga dilatih dengan prinsip machine learning dalam skala raksasa.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Tantangan dan Batasannya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Machine learning membutuhkan data yang banyak dan berkualitas — data yang bias menghasilkan keputusan yang bias. Model juga bisa "percaya diri tetapi salah", mengarang jawaban yang terdengar meyakinkan. Selain itu, pelatihannya memakan energi dan biaya komputasi yang besar, serta menimbulkan pertanyaan tentang privasi data dan lapangan kerja.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Masa Depan dan Peran Manusia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Arah perkembangannya menuju model yang lebih efisien, transparan, dan bisa menjelaskan alasannya. Namun satu hal tidak berubah: manusia tetap memegang peran menentukan tujuan, menilai hasil, dan bertanggung jawab atas keputusan. Memahami cara kerja machine learning membantu kita menjadi pengguna yang kritis, bukan sekadar penonton.$$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, siswa diharapkan mampu menentukan ruang sampel dan titik sampel suatu percobaan, menghitung peluang teoretis suatu kejadian, serta menghitung frekuensi harapan dari suatu percobaan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Materi: Ruang Sampel dan Titik Sampel$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Percobaan adalah kegiatan yang hasilnya tidak dapat dipastikan sebelumnya, misalnya melempar dadu. Ruang sampel adalah himpunan semua hasil yang mungkin, ditulis S. Titik sampel adalah setiap anggota ruang sampel. Contoh: pada pelemparan satu dadu, S = {1, 2, 3, 4, 5, 6}, dan setiap angka adalah titik sampel.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Materi: Rumus Peluang$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Peluang kejadian A dirumuskan P(A) = n(A) / n(S), dengan n(A) = banyak titik sampel kejadian A dan n(S) = banyak seluruh titik sampel. Nilai peluang selalu antara 0 dan 1. Peluang 0 berarti kejadian mustahil, peluang 1 berarti kejadian pasti. Contoh: peluang muncul mata dadu 5 adalah 1/6.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Contoh Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Sebuah koin dilempar sekali. Tentukan peluang muncul sisi gambar! Jawab: n(S) = 2, n(A) = 1, jadi P = 1/2.$txt$, $txt$Dari 10 bola (4 merah, 6 biru) diambil satu bola. Peluang terambil bola merah = 4/10 = 2/5.$txt$, $txt$Dua dadu dilempar. Peluang muncul jumlah mata dadu 7 = 6/36 = 1/6.$txt$, $txt$Frekuensi harapan adalah banyak kejadian yang diharapkan dari sejumlah percobaan: Fh = P(A) × banyak percobaan. Contoh: dadu dilempar 60 kali, harapan muncul mata 3 = 1/6 × 60 = 10 kali.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$txt$Sebuah dadu dilempar sekali. Tentukan peluang muncul mata dadu genap!$txt$, $txt$Dalam kotak ada 5 kelereng hijau dan 3 kelereng kuning. Diambil satu kelereng. Berapa peluang terambil kelereng kuning?$txt$, $txt$Sebuah koin dilempar 100 kali. Berapa frekuensi harapan muncul sisi angka?$txt$, $txt$Tentukan ruang sampel dari pelemparan dua koin sekaligus!$txt$, $txt$Peluang muncul mata dadu prima pada pelemparan satu dadu adalah ...$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$txt$1. Mata genap = {2,4,6}, P = 3/6 = 1/2.$txt$, $txt$2. n(S) = 8, n(kuning) = 3, P = 3/8.$txt$, $txt$3. P(angka) = 1/2, Fh = 1/2 × 100 = 50 kali.$txt$, $txt$4. S = {AA, AG, GA, GG}.$txt$, $txt$5. Mata prima = {2,3,5}, P = 3/6 = 1/2.$txt$]));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, siswa diharapkan mampu menjelaskan pengertian puisi, menyebutkan ciri-ciri puisi, membedakan bait dan baris, serta membaca puisi dengan lafal dan intonasi yang tepat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Materi: Pengertian dan Ciri-ciri Puisi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Puisi adalah karya sastra yang mengungkapkan pikiran dan perasaan penyair dengan bahasa yang indah dan bermakna. Ciri-ciri puisi: bahasanya singkat dan padat, memiliki irama (bunyi yang berulang), mengandung kiasan atau perumpamaan, dan ditulis dalam baris-baris yang tersusun dalam bait.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Contoh Puisi: Bait dan Baris$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Baris adalah satu larik kalimat dalam puisi, sedangkan bait adalah kumpulan beberapa baris yang membentuk satu kesatuan — mirip paragraf dalam karangan. Contoh puisi "Pagi di Desaku": Matahari terbit di ufuk timur / Burung-burung berkicau riang / Embun pagi menetes di daun / Desaku bangun menyambut terang. Puisi ini terdiri dari 1 bait dan 4 baris, dengan bunyi akhir yang selaras (timur-riang, daun-terang).$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Materi: Cara Membaca Puisi yang Baik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$txt$Bacalah dengan lafal yang jelas agar setiap kata terdengar.$txt$, $txt$Atur intonasi: naikkan suara pada bagian gembira, lembutkan pada bagian sedih.$txt$, $txt$Berhentilah sejenak di akhir setiap baris (jeda).$txt$, $txt$Tunjukkan ekspresi wajah sesuai isi puisi.$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$txt$Apa yang dimaksud dengan puisi?$txt$, $txt$Sebutkan tiga ciri-ciri puisi!$txt$, $txt$Apa perbedaan bait dan baris?$txt$, $txt$Buatlah satu bait puisi tentang sekolahmu (4 baris)!$txt$, $txt$Bacakan puisimu di depan kelas dengan intonasi yang tepat!$txt$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban dan Penjelasan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$txt$1. Puisi adalah karya sastra yang mengungkapkan pikiran dan perasaan dengan bahasa indah.$txt$, $txt$2. Bahasanya singkat-padat, berirama, mengandung kiasan. (jawaban lain yang tepat diterima)$txt$, $txt$3. Baris adalah satu larik; bait adalah kumpulan beberapa baris.$txt$, $txt$4-5. Dinilai dari kesesuaian tema, jumlah baris, dan cara membaca (lafal, intonasi, jeda).$txt$]));
